package store

// Statements below are copied byte-for-byte from protocols/db.py _init_db so that
// sqlite_master.sql of a freshly created database is identical to the one the
// Python server creates (whitespace included).

const (
	createMessagesSQL               = "\n                CREATE TABLE IF NOT EXISTS messages (\n                    id INTEGER PRIMARY KEY AUTOINCREMENT,\n                    protocol TEXT NOT NULL DEFAULT 'signal',\n                    contact_number TEXT NOT NULL,\n                    text TEXT,\n                    is_mine INTEGER NOT NULL DEFAULT 0,\n                    sender TEXT,\n                    timestamp INTEGER NOT NULL,\n                    quote_text TEXT,\n                    msg_type TEXT DEFAULT 'text',\n                    attachment_info TEXT,\n                    attachment_id TEXT,\n                    content_type TEXT,\n                    media_kind TEXT,\n                    quote_attachment_id TEXT,\n                    quote_attachment_path TEXT,\n                    quote_content_type TEXT,\n                    read INTEGER DEFAULT 0,\n                    status TEXT DEFAULT 'read',\n                    msg_id TEXT,\n                    quote_timestamp INTEGER,\n                    quote_author TEXT,\n                    reply_to_message_id TEXT,\n                    edited INTEGER NOT NULL DEFAULT 0,\n                    batch_id TEXT,\n                    batch_index INTEGER\n                )\n            "
	createReactionsSQL              = "\n                CREATE TABLE IF NOT EXISTS reactions (\n                    id INTEGER PRIMARY KEY AUTOINCREMENT,\n                    protocol TEXT NOT NULL,\n                    contact_number TEXT NOT NULL,\n                    target_msg_id TEXT,\n                    target_timestamp INTEGER,\n                    emoji TEXT NOT NULL,\n                    author_key TEXT NOT NULL DEFAULT '',\n                    author TEXT NOT NULL DEFAULT '',\n                    is_mine INTEGER NOT NULL DEFAULT 0,\n                    count INTEGER NOT NULL DEFAULT 1,\n                    timestamp INTEGER NOT NULL\n                )\n            "
	createTranscriptionsSQL         = "\n                CREATE TABLE IF NOT EXISTS transcriptions (\n                    protocol TEXT NOT NULL,\n                    attachment_id TEXT NOT NULL,\n                    status TEXT NOT NULL DEFAULT 'pending',\n                    text TEXT,\n                    error TEXT,\n                    model TEXT,\n                    updated_at REAL NOT NULL,\n                    PRIMARY KEY (protocol, attachment_id)\n                )\n            "
	createReactionsIdentityIndexSQL = "\n                    CREATE UNIQUE INDEX IF NOT EXISTS idx_reactions_identity\n                    ON reactions(protocol, contact_number,\n                                 IFNULL(target_msg_id, ''),\n                                 IFNULL(target_timestamp, 0), author_key)\n                "
	createReactionsContactIndexSQL  = "\n                    CREATE INDEX IF NOT EXISTS idx_reactions_contact\n                    ON reactions(protocol, contact_number)\n                "
)
